'use client';

import { useEffect, useRef } from 'react';
import {
    Copy,
    Trash2,
    Layers,
    AlignLeft,
    MoreVertical,
    Lock,
    Ungroup,
    Eye,
    Type
} from 'lucide-react';

export interface ContextMenuAction {
    id: string;
    label: string;
    icon: React.ReactNode;
    action: () => void;
    shortcut?: string;
    danger?: boolean;
}

interface ContextMenuProps {
    x: number;
    y: number;
    onClose: () => void;
    actions: ContextMenuAction[];
    selectedCount: number;
}

export function ContextMenu({ x, y, onClose, actions, selectedCount }: ContextMenuProps) {
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                onClose();
            }
        };

        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [onClose]);

    // Adjust position to keep within viewport
    const style = {
        top: Math.min(y, typeof window !== 'undefined' ? window.innerHeight - 200 : y),
        left: Math.min(x, typeof window !== 'undefined' ? window.innerWidth - 300 : x),
    };

    return (
        <div
            ref={menuRef}
            className="fixed z-50 flex flex-col items-start bg-gray-900/95 backdrop-blur-xl border border-white/10 rounded-xl shadow-2xl overflow-hidden min-w-[220px] animate-in fade-in zoom-in-95 duration-200"
            style={style}
        >
            {/* Header / Info */}
            <div className="w-full px-3 py-2 border-b border-white/5 bg-white/5 flex items-center justify-between">
                <span className="text-[10px] font-bold text-white/50 uppercase tracking-wider">
                    {selectedCount} Selected
                </span>
                <div className="flex gap-1">
                    <button className="p-1 hover:bg-white/10 rounded-md transition-colors" title="Lock">
                        <Lock className="w-3 h-3 text-white/40" />
                    </button>
                    <button className="p-1 hover:bg-white/10 rounded-md transition-colors" title="Visible">
                        <Eye className="w-3 h-3 text-white/40" />
                    </button>
                </div>
            </div>

            {/* Actions Grid (Primary) */}
            <div className="p-1 w-full grid grid-cols-4 gap-1 border-b border-white/5">
                <button
                    onClick={actions.find(a => a.id === 'duplicate')?.action}
                    className="p-2 hover:bg-blue-500/20 hover:text-blue-400 rounded-lg flex flex-col items-center gap-1 transition-colors group"
                    title="Duplicate (Ctrl+D)"
                >
                    <Layers className="w-4 h-4 text-white/60 group-hover:text-blue-400" />
                </button>
                <button className="p-2 hover:bg-white/10 rounded-lg flex flex-col items-center gap-1 transition-colors group">
                    <AlignLeft className="w-4 h-4 text-white/60 group-hover:text-white" />
                </button>
                <button className="p-2 hover:bg-white/10 rounded-lg flex flex-col items-center gap-1 transition-colors group">
                    <Type className="w-4 h-4 text-white/60 group-hover:text-white" />
                </button>
                <button className="p-2 hover:bg-white/10 rounded-lg flex flex-col items-center gap-1 transition-colors group">
                    <Ungroup className="w-4 h-4 text-white/60 group-hover:text-white" />
                </button>
            </div>

            {/* List Actions */}
            <div className="p-1 w-full flex flex-col">
                {actions.filter(a => a.id !== 'duplicate').map((action) => (
                    <button
                        key={action.id}
                        onClick={() => {
                            action.action();
                            onClose();
                        }}
                        className={`
              w-full px-3 py-2 text-left text-sm rounded-lg flex items-center justify-between group transition-colors
              ${action.danger
                                ? 'hover:bg-red-500/20 text-red-400'
                                : 'hover:bg-white/10 text-white/80 hover:text-white'
                            }
            `}
                    >
                        <div className="flex items-center gap-3">
                            {action.icon}
                            <span>{action.label}</span>
                        </div>
                        {action.shortcut && (
                            <span className={`text-[10px] font-mono opacity-40 group-hover:opacity-60`}>
                                {action.shortcut}
                            </span>
                        )}
                    </button>
                ))}
            </div>
        </div>
    );
}
