import React from 'react';
import {
    AlignLeft,
    AlignCenter,
    AlignRight,
    AlignVerticalJustifyStart,
    AlignVerticalJustifyCenter,
    AlignVerticalJustifyEnd,
    SeparatorHorizontal,
    SeparatorVertical
} from 'lucide-react';

export interface AlignmentAction {
    id: string;
    label: string;
    icon: React.ReactNode;
    action: () => void;
    disabled?: boolean;
}

export interface AlignmentToolbarProps {
    selectedCount: number;
    onAlign: (type: 'left' | 'center' | 'right' | 'top' | 'middle' | 'bottom') => void;
    onDistribute: (direction: 'horizontal' | 'vertical') => void;
}

export function AlignmentToolbar({ selectedCount, onAlign, onDistribute }: AlignmentToolbarProps) {
    const needsMultiple = selectedCount < 2;
    const needsThree = selectedCount < 3;

    const alignmentActions: AlignmentAction[] = [
        {
            id: 'align-left',
            label: 'Align Left',
            icon: <AlignLeft className="w-4 h-4" />,
            action: () => onAlign('left'),
            disabled: needsMultiple
        },
        {
            id: 'align-center',
            label: 'Align Center',
            icon: <AlignCenter className="w-4 h-4" />,
            action: () => onAlign('center'),
            disabled: needsMultiple
        },
        {
            id: 'align-right',
            label: 'Align Right',
            icon: <AlignRight className="w-4 h-4" />,
            action: () => onAlign('right'),
            disabled: needsMultiple
        },
        {
            id: 'align-top',
            label: 'Align Top',
            icon: <AlignVerticalJustifyStart className="w-4 h-4" />,
            action: () => onAlign('top'),
            disabled: needsMultiple
        },
        {
            id: 'align-middle',
            label: 'Align Middle',
            icon: <AlignVerticalJustifyCenter className="w-4 h-4" />,
            action: () => onAlign('middle'),
            disabled: needsMultiple
        },
        {
            id: 'align-bottom',
            label: 'Align Bottom',
            icon: <AlignVerticalJustifyEnd className="w-4 h-4" />,
            action: () => onAlign('bottom'),
            disabled: needsMultiple
        },
        {
            id: 'distribute-horizontal',
            label: 'Distribute Horizontally',
            icon: <SeparatorHorizontal className="w-4 h-4" />,
            action: () => onDistribute('horizontal'),
            disabled: needsThree
        },
        {
            id: 'distribute-vertical',
            label: 'Distribute Vertically',
            icon: <SeparatorVertical className="w-4 h-4" />,
            action: () => onDistribute('vertical'),
            disabled: needsThree
        }
    ];

    if (selectedCount === 0) return null;

    return (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-50">
            <div className="bg-gray-900/95 backdrop-blur-md border border-gray-700 rounded-xl shadow-2xl p-2 flex items-center gap-1">
                {/* Selection indicator */}
                <div className="px-3 py-1.5 text-xs font-medium text-gray-400 border-r border-gray-700 mr-1">
                    {selectedCount} selected
                </div>

                {/* Alignment buttons */}
                {alignmentActions.map((action, index) => (
                    <React.Fragment key={action.id}>
                        {/* Separator after horizontal alignments and vertical alignments */}
                        {(index === 3 || index === 6) && (
                            <div className="w-px h-6 bg-gray-700 mx-1" />
                        )}

                        <button
                            onClick={action.action}
                            disabled={action.disabled}
                            title={action.label}
                            className={`
                                p-2 rounded-lg transition-all
                                ${action.disabled
                                    ? 'text-gray-600 cursor-not-allowed'
                                    : 'text-gray-300 hover:text-white hover:bg-gray-800 active:scale-95'
                                }
                            `}
                        >
                            {action.icon}
                        </button>
                    </React.Fragment>
                ))}
            </div>
        </div>
    );
}
